function compute(inputs) {
  const Q = inputs.Q;
  const K = inputs.K;
  const V = inputs.V;
  const scaling = inputs.scaling;
  const dk = Q[0].length;
  const scale = scaling ? Math.sqrt(dk) : 1;
  const n = Q.length;
  const m = K.length;
  const scores = [];
  for (let i = 0; i < n; i++) {
    scores[i] = [];
    for (let j = 0; j < m; j++) {
      let dot = 0;
      for (let k = 0; k < dk; k++) {
        dot += Q[i][k] * K[j][k];
      }
      scores[i][j] = dot / scale;
    }
  }
  const weights = [];
  for (let i = 0; i < n; i++) {
    const row = scores[i];
    const maxScore = Math.max(...row);
    const exps = row.map(s => Math.exp(s - maxScore));
    const sumExps = exps.reduce((a, b) => a + b, 0);
    weights[i] = exps.map(e => e / sumExps);
  }
  const output = [];
  for (let i = 0; i < n; i++) {
    output[i] = [];
    for (let d = 0; d < V[0].length; d++) {
      let sum = 0;
      for (let j = 0; j < m; j++) {
        sum += weights[i][j] * V[j][d];
      }
      output[i][d] = sum;
    }
  }
  const tableRows = [];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      tableRows.push([`q${i+1}`, `k${j+1}`, scores[i][j].toFixed(3), weights[i][j].toFixed(3)]);
    }
  }
  const table = {
    columns: ['Query', 'Key', 'Score', 'Weight'],
    rows: tableRows
  };
  const rowSums = weights.map(row => row.reduce((a, b) => a + b, 0));
  const maxWeight = Math.max(...weights.flat());
  const insight = `Row sums of weights: ${rowSums.map(s => s.toFixed(3)).join(', ')}. Max weight: ${maxWeight.toFixed(3)}. ${scaling ? 'Scaling applied.' : 'No scaling.'}`;
  return {
    scores: scores,
    weights: weights,
    output: output,
    table: table,
    insight: insight
  };
}
